-- Rentals Phase 44: scoped maintenance request intake.
begin;
create table public.rental_maintenance_requests(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),property_id uuid not null references public.rental_properties(id),unit_id uuid not null references public.rental_units(id),tenancy_id uuid references public.rental_tenancies(id),category text not null check(category in('plumbing','electrical','appliance','security','structural','pest','cleaning','other')),priority text not null check(priority in('emergency','urgent','routine')),description text not null check(length(btrim(description))>=10),status text not null default 'submitted' check(status in('submitted','acknowledged','triaged','assigned','resolved','cancelled')),reported_by uuid not null references auth.users(id),reported_at timestamptz not null default now(),acknowledged_by uuid references auth.users(id),acknowledged_at timestamptz,duplicate_key text not null,unique(tenancy_id,duplicate_key));
create table public.rental_maintenance_request_media(id uuid primary key default gen_random_uuid(),request_id uuid not null references public.rental_maintenance_requests(id),media_link text not null,caption text,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create index rental_maintenance_requests_queue_idx on public.rental_maintenance_requests(organisation_id,status,priority,reported_at desc);alter table public.rental_maintenance_requests enable row level security;alter table public.rental_maintenance_request_media enable row level security;revoke all on public.rental_maintenance_requests,public.rental_maintenance_request_media from anon,authenticated;grant select on public.rental_maintenance_requests,public.rental_maintenance_request_media to authenticated;
create policy rental_maintenance_requests_read on public.rental_maintenance_requests for select to authenticated using(exists(select 1 from public.rental_properties p where p.id=property_id and public.rental_branch_access(p.organisation_id,p.branch_id)));create policy rental_maintenance_media_read on public.rental_maintenance_request_media for select to authenticated using(exists(select 1 from public.rental_maintenance_requests r join public.rental_properties p on p.id=r.property_id where r.id=request_id and public.rental_branch_access(p.organisation_id,p.branch_id)));
create or replace function public.rental_create_maintenance_request(p_tenancy uuid,p_category text,p_priority text,p_description text,p_media jsonb default '[]') returns jsonb language plpgsql security definer set search_path='' as $$declare t public.rental_tenancies%rowtype;rid uuid;k text;m jsonb;begin if auth.uid() is null or p_category not in('plumbing','electrical','appliance','security','structural','pest','cleaning','other') or p_priority not in('emergency','urgent','routine') or length(btrim(coalesce(p_description,'')))<10 or jsonb_typeof(p_media)<>'array' then raise exception 'Valid category, priority, description and media list required';end if;select * into t from public.rental_tenancies where id=p_tenancy for update;if not found or not exists(select 1 from public.rental_properties p where p.id=t.property_id and public.rental_branch_access(p.organisation_id,p.branch_id)) then raise exception 'Not authorized';end if;k:=md5(lower(btrim(p_category)||':'||btrim(p_description)||':'||current_date::text));insert into public.rental_maintenance_requests(organisation_id,property_id,unit_id,tenancy_id,category,priority,description,reported_by,duplicate_key) values(t.organisation_id,t.property_id,t.unit_id,t.id,p_category,p_priority,btrim(p_description),auth.uid(),k) on conflict(tenancy_id,duplicate_key) do update set reported_at=public.rental_maintenance_requests.reported_at returning id into rid;for m in select value from jsonb_array_elements(p_media) loop if length(coalesce(m->>'media_link',''))>0 then insert into public.rental_maintenance_request_media(request_id,media_link,caption,created_by) values(rid,m->>'media_link',m->>'caption',auth.uid());end if;end loop;return jsonb_build_object('request_id',rid,'priority',p_priority);end$$;
create or replace function public.rental_acknowledge_maintenance_request(p_request uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare r public.rental_maintenance_requests%rowtype;begin select * into r from public.rental_maintenance_requests where id=p_request for update;if not found or not exists(select 1 from public.rental_properties p where p.id=r.property_id and public.rental_branch_access(p.organisation_id,p.branch_id)) then raise exception 'Not authorized';end if;if r.status='submitted' then update public.rental_maintenance_requests set status='acknowledged',acknowledged_by=auth.uid(),acknowledged_at=now() where id=r.id;end if;return jsonb_build_object('request_id',r.id,'status','acknowledged');end$$;
revoke execute on function public.rental_create_maintenance_request(uuid,text,text,text,jsonb),public.rental_acknowledge_maintenance_request(uuid) from public,anon;grant execute on function public.rental_create_maintenance_request(uuid,text,text,text,jsonb),public.rental_acknowledge_maintenance_request(uuid) to authenticated;commit;
